const FORMAT='lyricforge-project-bundle';
function bytesToBase64(bytes){let binary='';const chunk=0x8000;for(let i=0;i<bytes.length;i+=chunk)binary+=String.fromCharCode(...bytes.subarray(i,i+chunk));return btoa(binary);}
function base64ToBytes(base64){const binary=atob(base64),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return bytes;}
export async function createProjectBundle(project,getAsset){const assets=[];for(const meta of project.assets||[]){const rec=await getAsset(meta.id);if(!rec?.blob)continue;const buf=new Uint8Array(await rec.blob.arrayBuffer());assets.push({id:meta.id,mime:rec.blob.type||meta.mime||'application/octet-stream',meta:rec.meta||meta,data:bytesToBase64(buf)});}const payload={format:FORMAT,version:1,createdAt:new Date().toISOString(),project:structuredClone(project),assets};return new Blob([JSON.stringify(payload)],{type:'application/vnd.lyricforge+json'});}
export async function restoreProjectBundle(text,putAsset){const payload=JSON.parse(text);if(payload.format!==FORMAT||!payload.project)throw new Error('Not a valid LyricForge project bundle.');for(const a of payload.assets||[]){const bytes=base64ToBytes(a.data||'');const blob=new Blob([bytes],{type:a.mime||'application/octet-stream'});await putAsset(a.id,blob,a.meta||{});}return payload.project;}
